Certainly! Below is a C# translation of your Python code for executing queries in parallel to multiple Amazon Redshift clusters.  
This version uses **Npgsql** for PostgreSQL/Redshift connectivity and **Tasks with async/await** for parallelism (the closest .NET analogue to Python's `ThreadPoolExecutor`).  
I've added comments to clarify each part.

**You'll need to install the `Npgsql` NuGet package:**  
```
dotnet add package Npgsql
```

**C# Code:**
```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Threading.Tasks;
using Npgsql;

namespace RedshiftParallelQuery
{
    // Class to store Redshift cluster credentials
    public class ClusterCredentials
    {
        public string Host { get; set; }
        public string DbName { get; set; }
        public string Port { get; set; }
        public string User { get; set; }
        public string Password { get; set; }
    }

    class Program
    {
        // The SQL query to execute
        private const string SqlQuery = "Your SQL Query Here";

        // Executes query on a Redshift cluster and returns results as a DataTable
        private static async Task<DataTable> ExecuteQueryRedshiftAsync(ClusterCredentials cluster)
        {
            // Build connection string
            var connString = $"Host={cluster.Host};Port={cluster.Port};Database={cluster.DbName};Username={cluster.User};Password={cluster.Password}";

            await using var conn = new NpgsqlConnection(connString);
            await using var cmd = new NpgsqlCommand(SqlQuery, conn);

            try
            {
                await conn.OpenAsync();

                var dt = new DataTable();
                await using (var reader = await cmd.ExecuteReaderAsync())
                {
                    dt.Load(reader);
                }

                return dt;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error occurred while connecting to Redshift ({cluster.Host}): {ex.Message}");
                return null;
            }
            finally
            {
                // Connections and readers are disposed with "await using"
                Console.WriteLine($"Redshift connection to {cluster.Host} is closed");
            }
        }

        static async Task Main(string[] args)
        {
            // List of clusters credentials
            var clusters = new List<ClusterCredentials>
            {
                new ClusterCredentials
                {
                    Host = "Cluster1_host",
                    DbName = "Cluster1_dbname",
                    Port = "Cluster1_port",
                    User = "Cluster1_user",
                    Password = "Cluster1_password"
                },
                new ClusterCredentials
                {
                    Host = "Cluster2_host",
                    DbName = "Cluster2_dbname",
                    Port = "Cluster2_port",
                    User = "Cluster2_user",
                    Password = "Cluster2_password"
                },
                // Add more clusters as needed
            };

            // Start one task per cluster
            var tasks = new List<Task<(ClusterCredentials, DataTable)>>();
            foreach (var cluster in clusters)
            {
                // For each cluster, execute the query in parallel (fire off Tasks)
                var task = Task.Run(async () =>
                {
                    var result = await ExecuteQueryRedshiftAsync(cluster);
                    return (cluster, result);
                });
                tasks.Add(task);
            }

            // Wait for all tasks to complete and process results
            while (tasks.Count > 0)
            {
                var finishedTask = await Task.WhenAny(tasks);
                tasks.Remove(finishedTask);
                var (cluster, result) = await finishedTask;

                if (result != null)
                {
                    Console.WriteLine($"Data from the cluster {cluster.Host}:");
                    foreach (DataRow row in result.Rows)
                    {
                        Console.WriteLine(string.Join(", ", row.ItemArray));
                    }
                }
                else
                {
                    Console.WriteLine($"No data returned from cluster {cluster.Host}");
                }
            }
        }
    }
}
```

---
**Key Points:**

- The `ExecuteQueryRedshiftAsync` function mirrors the Python function: establishes connection, executes the query, returns results (`DataTable`).
- **Tasks** are analogous to threads (but more efficient in .NET for IO-bound work).
- The code prints each cluster's results as soon as they finish (like Python's `as_completed`).
- Proper use of `using`/`await using` ensures connections, commands, and readers are disposed/closed, similar to Python's `finally`.
- Error handling is done with try/catch, and results are set to `null` on failures.
- To run, place the code in a Console Project, replace credentials/query as needed, and ensure `Npgsql` is installed.

