Certainly! Let's walk through how to **transpose a two-dimensional matrix** in C++ using your example.

### The Problem

Given a matrix:

```
1 2 3
4 5 6
7 8 9
```

The **transpose** swaps matrix[i][j] with matrix[j][i], so the result is:

```
1 4 7
2 5 8
3 6 9
```

---

### Step-by-Step C++ Solution

#### 1. Include necessary headers

```cpp
#include <iostream>
#include <vector>
```

#### 2. Define and Print the Matrix

```cpp
void printMatrix(const std::vector<std::vector<int>>& matrix) {
    for (const auto& row : matrix) {
        for (int val : row)
            std::cout << val << " ";
        std::cout << "\n";
    }
}
```

#### 3. Transpose Function

```cpp
std::vector<std::vector<int>> transpose(const std::vector<std::vector<int>>& matrix) {
    int n = matrix.size();           // number of rows
    int m = matrix[0].size();        // number of columns
    std::vector<std::vector<int>> result(m, std::vector<int>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            result[j][i] = matrix[i][j];
        }
    }
    return result;
}
```

#### 4. Complete Example

```cpp
#include <iostream>
#include <vector>

void printMatrix(const std::vector<std::vector<int>>& matrix) {
    for (const auto& row : matrix) {
        for (int val : row)
            std::cout << val << " ";
        std::cout << "\n";
    }
}

std::vector<std::vector<int>> transpose(const std::vector<std::vector<int>>& matrix) {
    int n = matrix.size();
    int m = matrix[0].size();
    std::vector<std::vector<int>> result(m, std::vector<int>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            result[j][i] = matrix[i][j];
        }
    }
    return result;
}

int main() {
    std::vector<std::vector<int>> example_matrix = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };

    std::cout << "Original Matrix:\n";
    printMatrix(example_matrix);

    auto transposed_matrix = transpose(example_matrix);

    std::cout << "\nTransposed Matrix:\n";
    printMatrix(transposed_matrix);

    return 0;
}
```

---

### Output

```
Original Matrix:
1 2 3 
4 5 6 
7 8 9 

Transposed Matrix:
1 4 7 
2 5 8 
3 6 9 
```

