```python
import datetime

class Automobile:
    _available_colors = {"red", "blue", "black", "white", "silver", "green", "yellow"}  # Predefined color list

    def __init__(self, color, model, year):
        self._color = color if color in self._available_colors else "black"
        self._model = None      # set via public setter below
        self._year = None       # set via public setter below
        self.set_model(model)
        self.set_year(year)

    # Color getter/setter
    def get_color(self):
        return self._color

    def set_color(self, color):
        if color in self._available_colors:
            print(f"Color of the car has been changed to {color}.")
            self._color = color
            return True
        else:
            print(f"Color change failed. '{color}' is not in available colors: {self._available_colors}")
            return False

    # Model getter - no public setter after initialization
    def get_model(self):
        return self._model

    def set_model(self, model):
        if self._model is None:
            self._model = model
        else:
            raise AttributeError("Model can only be set once and cannot be modified afterwards.")

    # Year getter - no public setter after initialization
    def get_year(self):
        return self._year

    def set_year(self, year):
        if self._year is None:
            self._year = year
        else:
            raise AttributeError("Year can only be set once and cannot be modified afterwards.")

    # Calculate car age
    def get_age(self):
        current_year = datetime.datetime.now().year
        return current_year - self._year

    # For pretty printing
    def __str__(self):
        return f"{self._color.title()} {self._model} ({self._year})"

# Model hierarchy

class Model:
    """Base Model class."""
    def __str__(self):
        return self.__class__.__name__

class Sedan(Model):
    def __init__(self, num_doors=4, trunk_size=400):
        self.num_doors = num_doors
        self.trunk_size = trunk_size  # in liters

    def __str__(self):
        return f"Sedan (Doors: {self.num_doors}, Trunk: {self.trunk_size}L)"

class SUV(Model):
    def __init__(self, num_seats=7, four_wheel_drive=True):
        self.num_seats = num_seats
        self.four_wheel_drive = four_wheel_drive

    def __str__(self):
        return f"SUV (Seats: {self.num_seats}, 4WD: {'Yes' if self.four_wheel_drive else 'No'})"

class Coupe(Model):
    def __init__(self, sporty=True):
        self.sporty = sporty

    def __str__(self):
        return f"Coupe (Sporty: {'Yes' if self.sporty else 'No'})"

# ----- Driver Program -----

def main():
    sedan_model = Sedan(num_doors=4, trunk_size=450)
    suv_model = SUV(num_seats=5, four_wheel_drive=False)
    coupe_model = Coupe(sporty=True)

    car1 = Automobile("blue", sedan_model, 2018)
    car2 = Automobile("green", suv_model, 2015)
    car3 = Automobile("purple", coupe_model, 2020)  # "purple" not available; will default to "black"

    print("\n--- Automobile Objects ---")
    print(car1)
    print(car2)
    print(car3)

    print("\n--- Properties and Methods ---")
    print(f"Car1 Model: {car1.get_model()}")
    print(f"Car2 Year: {car2.get_year()}")
    print(f"Car3 Color: {car3.get_color()}")

    print("\n--- Changing Color ---")
    car1.set_color("silver")  # Should succeed
    car2.set_color("purple")  # Should fail

    print("\n--- Calculating Age ---")
    print(f"Car1 age: {car1.get_age()} years")
    print(f"Car2 age: {car2.get_age()} years")
    print(f"Car3 age: {car3.get_age()} years")

    print("\n--- Test Model/Year Immutability ---")
    try:
        car1.set_model(suv_model)
    except AttributeError as e:
