class ListManager:
    def __init__(self):
        self.list1 = []
        self.list2 = []

    def add_element(self, list_number, element):
        if not isinstance(element, (int, float)):
            raise TypeError("Only integer or float values can be added.")
        if list_number == 1:
            self.list1.append(element)
        elif list_number == 2:
            self.list2.append(element)
        else:
            raise ValueError("Invalid list number. Use 1 or 2.")

    def delete_element(self, list_number, element):
        target_list = self._get_list_by_number(list_number)
        if not target_list:
            raise IndexError("Cannot delete from empty list.")
        try:
            target_list.remove(element)
        except ValueError:
            raise ValueError(f"Element {element} not found in list {list_number}.")

    def merge_lists(self):
        return self.list1 + self.list2

    def sort_merged_list(self):
        merged = self.merge_lists()
        return sorted(merged)

    def _get_list_by_number(self, list_number):
        if list_number == 1:
            return self.list1
        elif list_number == 2:
            return self.list2
        else:
            raise ValueError("Invalid list number. Use 1 or 2.")
