    case 'C to F':
      // Celsius to Fahrenheit: (°C × 9/5) + 32 = °F
      return (value * 9/5) + 32;
    case 'F to C':
      // Fahrenheit to Celsius: (°F − 32) × 5/9 = °C
      return (value - 32) * 5/9;
    case 'K to F':
      // Kelvin to Fahrenheit: (K − 273.15) × 9/5 + 32 = °F
      return (value - 273.15) * 9/5 + 32;
    default:
      throw new Error(
        "Invalid conversion type. Use 'C to F', 'F to C', or 'K to F'."
      );
  }
}

