```java
import java.util.Scanner;

public class P2 {

    // The board
    static String[][] board;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        while (true) {
            System.out.print("Please enter size of board (need to be 2^n and 0 to quit): ");
            int size;
            if (sc.hasNextInt()) size = sc.nextInt();
            else {
                sc.nextLine(); // consume bad input
                continue;
            }
            if (size == 0)
                break;
            // Check if size is power of 2
            if ((size & (size - 1)) != 0) {
                System.out.println("The board size should be a power of 2");
                continue;
            }
            System.out.print("Please enter coordinates of missing square (seperated by a space): ");
            int x_missing = sc.nextInt();
            int y_missing = sc.nextInt();
            if (x_missing < 0 || x_missing >= size || y_missing < 0 || y_missing >= size) {
                System.out.println("Invalid coordinates.");
                continue;
            }
            // Initialize board
            board = new String[size][size];
            // Mark missing square
            board[y_missing][x_missing] = "MS";
            // Call the recursive tromino
            tromino(0, 0, x_missing, y_missing, size);

            // Print the board (row by row, highest y at top)
            for (int i = size - 1; i >= 0; i--) {    // Print y = size-1 down to y = 0
                for (int j = 0; j < size; j++) {     // x = 0 (left) to x = size-1 (right)
                    System.out.print(board[i][j]);
                    if (j < size - 1) System.out.print(" ");
                }
                System.out.println();
            }
        }
    }

    /**
     * Recursive tromino tiler.
     */
    static void tromino(int x_board, int y_board, int x_missing, int y_missing, int board_size) {
        if (board_size == 2) {
            // Fill in the three other squares (besides the missing one)
            for (int dy = 0; dy < 2; dy++) {
                for (int dx = 0; dx < 2; dx++) {
                    int x = x_board + dx;
                    int y = y_board + dy;
                    if (x == x_missing && y == y_missing) continue;
                    // Which L type to print?
                    // missing square can be at (x_board, y_board) ... (x_board+1, y_board+1)
                    // Let's determine the type by the location of the missing square
                    // (0,0): UR
                    // (1,0): UL
                    // (0,1): LR
                    // (1,1): LL
                    if (x_missing == x_board && y_missing == y_board)
                        board[y][x] = "UR";
                    else if (x_missing == x_board + 1 && y_missing == y_board)
                        board[y][x] = "UL";
                    else if (x_missing == x_board && y_missing == y_board + 1)
                        board[y][x] = "LR";
                    else
                        board[y][x] = "LL";
                }
            }
            return;
        }

        int half = board_size / 2;

        // Identify which quadrant the missing square is in:
        // 0: LL (lower left), 1: LR (lower right), 2: UL (upper left), 3: UR (upper right)
        // Board layout:
        // (x_board+half, y_board+half)
        //
        // (x_board, y_board+half)      (x_board+half, y_board+half)
        //      UL         |         UR
        //  ------------+-----------
        //      LL         |         LR
        // (x_board, y_board)      (x_board+half, y_board)
        int quad = 0;
        if (x_missing < x_board + half) {
            if (y_missing < y_board + half) quad = 0;      // LL
            else quad = 2;                                 // UL
        } else {
            if (y_missing < y_board + half) quad = 1;      // LR
            else quad = 3;                                 // UR
        }

        // Coordinates for the centers of each subboard
        int center_x = x_board + half - 1;
        int center_y = y_board + half - 1;
        // Place the L-shaped tromino in the center, avoiding the quadrant with the missing square
        // The "missing square" for each of the 4 quadrants:
        // For the quadrant containing the original missing, that missing square is preserved
        // For the other three, the "missing" square is the corner of the center L (so they get covered next)

        // Place center L tromino, mark on the board:
        // UL: (center_x, center_y+1)
        // UR: (center_x+1, center_y+1)
        // LL: (center_x, center_y)
        // LR: (center_x+1, center_y)

        if (quad != 2) board[center_y+1][center_x] = "LR"; // upper left
        if (quad != 3) board[center_y+1][center_x+1] = "LL"; // upper right
        if (quad != 0) board[center_y][center_x] = "UR"; // lower left
        if (quad != 1) board[center_y][center_x+1] = "UL"; // lower right

        // Now, recurse on each quadrant, using the proper missing square
        // Upper Left
        if (quad == 2) tromino(x_board, y_board+half, x_missing, y_missing, half);
        else tromino(x_board, y_board+half, center_x, center_y+1, half);
        // Upper Right
        if (quad == 3) tromino(x_board+half, y_board+half, x_missing, y_missing, half);
        else tromino(x_board+half, y_board+half, center_x+1, center_y+1, half);
        // Lower Left
        if (quad == 0) tromino(x_board, y_board, x_missing, y_missing, half);
        else tromino(x_board, y_board, center_x, center_y, half);
        // Lower Right
        if (quad == 1) tromino(x_board+half, y_board, x_missing, y_missing, half);
        else tromino(x_board+half, y_board, center_x+1, center_y, half);
    }
}
```

---

### How It Works:

1. **Board is indexed as** `board[y][x]` with origin `(0,0)` (bottom left).
2. The `tromino()` function places L-shapes in the center as required and recursively works on the four subboards.
3. The correct **"LL", "LR", "UL", "UR"** markers are printed as shown in your sample output.
4. Handles power-of-2 and input error checking as specified.

