```jsx
import React, { useState, useEffect } from "react";

function UserTimezoneClock() {
  // Get user's timezone from the browser
  const userTimeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;

  const [now, setNow] = useState(new Date());

  useEffect(() => {
    const interval = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(interval);
  }, []);

  // Formatting options
  const options = {
    year: "numeric",
    month: "long",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    timeZoneName: "short",
    hour12: false,
    timeZone: userTimeZone
  };

  const formatted = now.toLocaleString(undefined, options);

  return (
    <div>
      <h2>Your Local Time</h2>
      <p>
        <strong>{formatted}</strong>
      </p>
      <p style={{ fontSize: 'smaller', color: '#888' }}>
        Timezone: {userTimeZone}
      </p>
    </div>
  );
}

export default UserTimezoneClock;
```

