    int[][] array = { {3, 5, 9, 4}, {8, 6, 1, 7}, {2, 11, 5, 0} };
    int[] res = findLargestThree(array);
    System.out.println("Largest three numbers: " + res[0] + ", " + res[1] + ", " + res[2]);
}
