Certainly! Detecting a browser’s **rendering engine** (Blink, WebKit, Gecko, Trident, EdgeHTML, etc.) and its version is tricky because browsers frequently mask or change their user agent strings. However, we can make a reasonable best-effort based on the `navigator.userAgent` and `navigator.userAgentData` (if available).

Here’s a standalone JavaScript snippet to detect the current rendering engine and its version:

```javascript
function detectEngine() {
  const ua = navigator.userAgent;

  // Edge (Chromium)
  if (ua.includes('Edg/')) {
    const version = ua.match(/Edg\/([\d.]+)/);
    return { engine: 'Blink (Edge/Chromium)', version: version ? version[1] : 'unknown' };
  }
  // Chrome
  if (ua.includes('Chrome/')) {
    const version = ua.match(/Chrome\/([\d.]+)/);
    // Edge Chromium pretends to be Chrome. Already filtered above.
    return { engine: 'Blink (Chrome)', version: version ? version[1] : 'unknown' };
  }
  // Opera
  if (ua.includes('OPR/')) {
    const version = ua.match(/OPR\/([\d.]+)/);
    return { engine: 'Blink (Opera)', version: version ? version[1] : 'unknown' };
  }
  // Chromium browsers might include this
  if (ua.includes('Chromium/')) {
    const version = ua.match(/Chromium\/([\d.]+)/);
    return { engine: 'Blink (Chromium)', version: version ? version[1] : 'unknown' };
  }
  // Firefox
  if (ua.includes('Gecko/') && ua.includes('Firefox/')) {
    const version = ua.match(/rv:([\d.]+)/) || ua.match(/Firefox\/([\d.]+)/);
    return { engine: 'Gecko', version: version ? version[1] : 'unknown' };
  }
  // Safari (not Chrome)
  if (ua.includes('Safari/') && !ua.includes('Chrome/')) {
    const version = ua.match(/Version\/([\d.]+)/);
    return { engine: 'WebKit (Safari)', version: version ? version[1] : 'unknown' };
  }
  // Trident (IE)
  if (ua.includes('Trident/')) {
    const version = ua.match(/rv:([\d.]+)/) || ua.match(/Trident\/([\d.]+)/);
    return { engine: 'Trident (IE)', version: version ? version[1] : 'unknown' };
  }
  // Edge (Legacy)
  if (ua.includes('Edge/')) {
    const version = ua.match(/Edge\/([\d.]+)/);
    return { engine: 'EdgeHTML', version: version ? version[1] : 'unknown' };
  }
  // Default fallback
  return { engine: 'Unknown', version: 'unknown' };
}

// Example usage:
const engineInfo = detectEngine();
console.log(`Rendering engine: ${engineInfo.engine}, version: ${engineInfo.version}`);
