struct SufArr {
    string t;
    int len;
    vector<int> sa, rk, lcp;
    vector<vector<int>> rmq;
    vector<int> logt;

    SufArr(const string &txt) : t(txt), len(txt.size()) {
        sa = SA::build(t);
        rk.resize(len);
        for (int i=0; i<len; ++i) rk[sa[i]]=i;
        buildLCP();
        prepRMQ();
    }

    void buildLCP() {
        lcp.resize(len-1);
        int k=0;
        for (int i=0;i<len;++i) {
            if (rk[i]==len-1) {k=0; continue;}
            int j=sa[rk[i]+1];
            while (i+k<len && j+k<len && t[i+k]==t[j+k]) ++k;
            lcp[rk[i]]=k;
            if (k) --k;
        }
    }
    void prepRMQ() {
        int n=lcp.size();
        logt.assign(n+1,0);
        for (int i=2;i<=n;++i) logt[i]=logt[i>>1]+1;
        rmq.assign(n,vector<int>(logt[n]+1));
        for (int i=0;i<n;++i) rmq[i][0]=lcp[i];
        for (int k=1;(1<<k)<=n;++k)
            for (int i=0;i+(1<<k)<=n;++i)
                rmq[i][k]=min(rmq[i][k-1],rmq[i+(1<<(k-1))][k-1]);
    }
    int getLCP(int i, int j) {
        if (i==j) return len-i;
        int l=rk[i], r=rk[j];
        if (l>r) std::swap(l,r);
        ++l;
        int h=logt[r-l+1];
        return min(rmq[l][h], rmq[r-(1<<h)+1][h]);
    }
    // ... можно добавить больше функционала при желании
};

