#### **Active Directory Enumeration**
```csharp
public static List<string> GetActiveDirectoryDomains()
{
    List<string> domains = new List<string>();
    using (var rootDSE = new DirectoryEntry("LDAP://RootDSE"))
    {
        string configNC = rootDSE.Properties["configurationNamingContext"].Value.ToString();
        string ldapPath = $"LDAP://CN=Partitions,{configNC}";
        using (var dePartitions = new DirectoryEntry(ldapPath))
        {
            foreach (DirectoryEntry de in dePartitions.Children)
            {
                if (de.Properties["nCName"].Value != null)
                {
                    domains.Add(de.Properties["nCName"].Value.ToString());
                }
            }
        }
    }
    return domains;
}
```
