  if (arr.length === 0) return null;
  let signProduct = 1;
  let magnitudeSum = 0;
  for (let i = 0; i < arr.length; i++) {
    signProduct *= Math.sign(arr[i]);
    magnitudeSum += Math.abs(arr[i]);
  }
  return magnitudeSum * signProduct;
};
```

Or, as a **one-liner with reduce**:

```js
const prodSigns = (arr) => {
  if (arr.length === 0) return null;
  const signProduct = arr.reduce((prod, x) => prod * Math.sign(x), 1);
  const magnitudeSum = arr.reduce((sum, x) => sum + Math.abs(x), 0);
  return magnitudeSum * signProduct;
};
```

