- **Swapping case**: Use `std::toupper` and `std::tolower`.
- **Checking if a character is digit or punctuation**: Use `std::isdigit`, `std::ispunct` from `<cctype>`.
- **Tallying characters**: Use `std::unordered_map`.
- **Return:** In C++, we can use `std::pair<std::string, std::unordered_map<std::string, int>>`.

Here's a close C++ equivalent:

```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <cctype>

using namespace std;

pair<string, unordered_map<string, int>> swap_case_special(const string& f_string) {
    string transformed_string;
    unordered_map<string, int> tally;

    for (char f_char : f_string) {
        string transformed_char;

        // Check for digit and if it's odd
        if (isdigit(f_char) && (f_char - '0') % 2 != 0) {
            transformed_char = to_string((f_char - '0') + 1);
        }
        // Check if it's punctuation
        else if (ispunct(f_char)) {
            transformed_char = string(2, f_char);
        }
        // Else swap case
        else {
            if (islower(f_char))
                transformed_char += toupper(f_char);
            else if (isupper(f_char))
                transformed_char += tolower(f_char);
            else
                transformed_char += f_char;
        }

        tally[transformed_char]++;
        transformed_string += transformed_char;
    }

    return {transformed_string, tally};
}

