import java.util.List;

public class PercentileCalculator {
    /**
     * Return nth-percentiles of elements in the list l without sorting it.
     * Handles lists with numeric types, including negative and floating-point numbers.
     * Implements error handling for empty lists, non-integer values of n,
     * lists with less than n elements and invalid types.
     */
    public static double efficientNthPercentiles(List<Number> l, int n) {
        // error check for empty lists or non integer values of n
        if (l == null || l.isEmpty() || n <= 0) {
            throw new IllegalArgumentException(
                "Input list cannot be empty and n should be an integer greater than zero."
            );
        }

        // error check for lists with less than n elements
        if (l.size() < n) {
            throw new IllegalArgumentException(
                "The list should contain at least n number of elements."
            );
        }

        // error check for invalid types (Strings or Complex)
        for (Number value : l) {
            if (value instanceof Float && ((Float)value).isNaN()
                || value instanceof Double && ((Double)value).isNaN()) {
                throw new IllegalArgumentException("NaN values are not supported.");
            }
            if (value instanceof java.math.BigDecimal || value instanceof java.math.BigInteger) {
                continue;
            }
            if (!(value instanceof Integer || value instanceof Long
                    || value instanceof Float || value instanceof Double
                    || value instanceof Short || value instanceof Byte)) {
                throw new IllegalArgumentException("Unsupported number type: " + value.getClass());
            }
        }

        // Calculate the sum
        double sum = 0;
        for (Number value : l) {
            sum += value.doubleValue();
        }

        // Calculate nth percentile (according to your formula)
        return (sum / l.size()) * n / 100.0;
    }
}
