const vsSource = `#version 300 es
in vec3 aPosition;
in vec3 aNormal;
in vec2 aTexCoord;
in vec3 aTangent;

uniform mat4 uModel, uView, uProjection;
out vec2 vTexCoord;
out vec3 vNormal, vPosition, vTangent;

void main() {
  vTexCoord = aTexCoord;
  vNormal = mat3(uModel) * aNormal;
  vTangent = mat3(uModel) * aTangent;
  vec4 worldPosition = uModel * vec4(aPosition, 1.0);
  vPosition = worldPosition.xyz;
  gl_Position = uProjection * uView * worldPosition;
}
`;

const fsSource = `#version 300 es
precision highp float;
in vec2 vTexCoord;
in vec3 vNormal, vPosition, vTangent;

uniform sampler2D uTexture;
uniform sampler2D uBumpMap;
uniform samplerCube uEnvMap;
uniform bool uUseEnv;
uniform float uMixEnv;

uniform vec3 uCameraPosition;
out vec4 outColor;

void main() {
  // Texture mapping
  vec3 baseCol = texture(uTexture, vTexCoord).rgb;

  // Bump mapping (simple normal perturbation)
  vec3 normalMap = texture(uBumpMap, vTexCoord).xyz * 2.0 - 1.0;
  vec3 N = normalize(vNormal + normalMap * 0.45);

  // Environment mapping
  vec3 viewDir = normalize(uCameraPosition - vPosition);
  vec3 reflected = reflect(-viewDir, N);
  vec3 envCol = texture(uEnvMap, reflected).rgb;

  vec3 finalCol = mix(baseCol, envCol, uMixEnv);

  // Add basic lighting
  float diff = max(dot(N, normalize(vec3(0.2, 0.9, 1.0))), 0.0);
  finalCol *= diff * 0.8 + 0.2;

  outColor = vec4(finalCol, 1.0);
}
`;

///////////////////////
// Shaders/Program
///////////////////////
function createShader(gl, source, type) {
  const sh = gl.createShader(type);
  gl.shaderSource(sh, source);
  gl.compileShader(sh);
  if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS))
    throw new Error(gl.getShaderInfoLog(sh));
  return sh;
}
function createProgram(gl, vs, fs) {
  const prg = gl.createProgram();
  gl.attachShader(prg, vs); gl.attachShader(prg, fs); gl.linkProgram(prg);
  if (!gl.getProgramParameter(prg, gl.LINK_STATUS))
    throw new Error(gl.getProgramInfoLog(prg));
  return prg;
}

const vs = createShader(gl, vsSource, gl.VERTEX_SHADER);
const fs = createShader(gl, fsSource, gl.FRAGMENT_SHADER);
