const bufInstanceMat = gl.createBuffer();
gl.bindBuffer(gl.ARRAY_BUFFER, bufInstanceMat);
gl.bufferData(gl.ARRAY_BUFFER, modelMatrices, gl.DYNAMIC_DRAW);
const locModel = gl.getAttribLocation(prog, 'uModel');
for(let i=0;i<4;i++) { // mat4 splits into 4 vec4 attributes
  gl.vertexAttribPointer(locModel+i, 4, gl.FLOAT, false, 64, i*16);
  gl.vertexAttribDivisor(locModel+i, 1);
  gl.enableVertexAttribArray(locModel+i);
}
gl.drawElementsInstanced(gl.TRIANGLES, sphere.indices.length, gl.UNSIGNED_SHORT, 0, instanceCount);
```

