use strict;
use warnings;
use utf8;  # Allow Unicode input and output

sub highest_palindrome {
    my ($data) = @_;
    my @palindromes;

    # If it's a Range: expect a reference to an array indicating the range, e.g. [1 .. 1000]
    if (ref($data) eq 'ARRAY' && @$data && !ref($data->[0])) {
        # Check if all elements are integers
        if (grep { /\D/ } @$data) {  # Contains non-digits
            # Not an array of ints; fall through
        } else {
            foreach my $i (@$data) {
                my $str = "$i";
                if ($str eq reverse($str)) {
                    push @palindromes, $i;
                }
            }
        }
    }
    # If it's a List of Strings
    elsif (ref($data) eq 'ARRAY' && @$data && !defined($data->[0]) || ref($data->[0]) eq '') {
        foreach my $s (@$data) {
            next unless defined($s) && !ref($s);
            # Unicode-aware reverse
            my $rev = join('', reverse(split(//u, $s)));
            if ($s eq $rev) {
                push @palindromes, $s;
            }
        }
    }
    else {
        die "Input must be either an arrayref of integers or an arrayref of strings.\n";
    }

    if (!@palindromes) {
        return 0;
    }
    else {
        # Return the max by length, then by lexicographic (number for ints, string otherwise)
        my $max = $palindromes[0];
        foreach my $p (@palindromes) {
            if (length("$p") > length("$max") ||
                (length("$p") == length("$max") && "$p" gt "$max")) {
                $max = $p;
            }
        }
        return $max;
    }
}

# Usage examples:
#print highest_palindrome([100..200]), "\n";
#print highest_palindrome(['abc', 'ada', 'xyzzyx', 'лаал']), "\n";
