import { Injectable } from '@angular/core';
import { Book } from '../../models/book.model';
import { Observable, BehaviorSubject, of } from 'rxjs';

@Injectable({ providedIn: 'root' })
export class BookService {
  private books: Book[] = [
    {
      id: 1,
      title: 'Angular Fundamentals',
      author: 'Jane Doe',
      publicationDate: new Date('2021-05-20'),
      genre: 'Programming',
      description: 'A thorough guide to Angular.',
      ratings: []
    }
  ];
  private booksSubject = new BehaviorSubject<Book[]>(this.books);

  getBooks(): Observable<Book[]> {
    return this.booksSubject.asObservable();
  }
  getBook(id: number): Observable<Book | undefined> {
    return of(this.books.find(b => b.id === id));
  }
  addBook(book: Book) {
    book.id = Date.now();
    book.ratings = [];
    this.books.push(book);
    this.booksSubject.next(this.books);
  }
  updateBook(book: Book) {
    const idx = this.books.findIndex(b => b.id === book.id);
    if (idx >= 0) {
      this.books[idx] = book;
      this.booksSubject.next(this.books);
    }
  }
  deleteBook(id: number) {
    this.books = this.books.filter(b => b.id !== id);
    this.booksSubject.next(this.books);
  }
  rateBook(bookId: number, userId: number, rating: number) {
    const book = this.books.find(b => b.id === bookId);
    if (!book) return;
    const existing = book.ratings.find(r => r.userId === userId);
    if (existing) existing.rating = rating;
    else book.ratings.push({ userId, rating });
    this.booksSubject.next(this.books);
  }
}
