import { Component, OnInit } from '@angular/core';
import { BookService } from '../book.service';
import { AuthService } from '../../auth/auth.service';
import { Book } from '../../models/book.model';

@Component({
  selector: 'app-book-list',
  templateUrl: './book-list.component.html'
})
export class BookListComponent implements OnInit {
  books: Book[] = [];
  genres: string[] = [];
  filter = { author: '', genre: '', date: '' };
  sortField = '';
  userId!: number;
  isAdmin = false;

  constructor(private bookService: BookService, private auth: AuthService) {}

  ngOnInit() {
    this.bookService.getBooks().subscribe(books => {
      this.books = books;
      this.genres = [...new Set(books.map(b => b.genre))];
    });
    this.userId = this.auth.currentUser?.id ?? 0;
    this.isAdmin = this.auth.isAdmin();
  }

  filteredBooks(): Book[] {
    let filtered = [...this.books];
    if (this.filter.author)
      filtered = filtered.filter(b =>
        b.author.toLowerCase().includes(this.filter.author.toLowerCase()));
    if (this.filter.genre)
      filtered = filtered.filter(b => b.genre === this.filter.genre);
    if (this.filter.date)
      filtered = filtered.filter(b => b.publicationDate >= new Date(this.filter.date));
    if (this.sortField) {
      filtered = filtered.sort((a, b) => {
        if (this.sortField === 'publicationDate')
          return (new Date(a.publicationDate) as any) - (new Date(b.publicationDate) as any);
        return (a[this.sortField] as any).localeCompare(b[this.sortField]);
      });
    }
    return filtered;
  }

  delete(id: number) {
    if (confirm('Delete this book?')) this.bookService.deleteBook(id);
  }

  averageRating(book: Book): number {
    if (!book.ratings.length) return 0;
    return book.ratings.reduce((sum, r) => sum + r.rating, 0) / book.ratings.length;
  }
}
