let conditions: [(Int) -> Bool] = [
    { $0 > 1 },            // greater than 1
    { $0 % 2 == 1 }        // odd
]

if let result = pluck(arr: arr, condFnList: conditions) {
    print(result)   // (element: 3, index: 0)
} else {
    print("No match found")
}
