```go
package main

import (
	"errors"
	"fmt"
	"time"
)

// User represents a blogging user
type User struct {
	Name             string
	Email            string
	RegistrationDate time.Time
	Posts            []*Post // List of pointers to Posts authored by the user
}

// Post represents a blog post
type Post struct {
	Title     string
	Author    *User      // Pointer for relationship integrity (avoiding cyclic import)
	Timestamp time.Time
	Body      string
	Comments  []*Comment // Slice of pointers to comments
}

// AddComment adds a comment to the Post. It checks if newComment is non-nil and has a non-empty body.
func (p *Post) AddComment(newComment *Comment) error {
	if newComment == nil {
		return errors.New("comment cannot be nil")
	}
	if newComment.Body == "" {
		return errors.New("comment body cannot be empty")
	}
	p.Comments = append(p.Comments, newComment)
	return nil
}

// Comment represents a comment or a reply (comments and replies are of the same type)
type Comment struct {
	User      *User
	Timestamp time.Time
	Body      string
	Replies   []*Comment // Slice of pointers to replies (nested comments)
}

// AddReply adds a reply to this comment.
func (c *Comment) AddReply(reply *Comment) error {
	if reply == nil {
		return errors.New("reply cannot be nil")
	}
	if reply.Body == "" {
		return errors.New("reply body cannot be empty")
	}
	c.Replies = append(c.Replies, reply)
	return nil
}

