// Responsive Navigation Menu Mixin (SCSS)
@mixin responsive-nav-menu(
  $bg-color: #333,
  $link-color: #f2f2f2,
  $link-hover-bg: #111,
  $link-padding: 16px
) {
  width: 100%;
  background-color: $bg-color;
  display: flex;
  flex-direction: row;
  justify-content: flex-start;
  align-items: center;

  a {
    color: $link-color;
    text-align: center;
    padding: $link-padding;
    text-decoration: none;
    transition: background-color 0.2s;
    flex: 1 1 auto;
    &:hover,
    &:focus {
      background-color: $link-hover-bg;
    }
  }

  @media screen and (max-width: 600px), (orientation: portrait) {
    flex-direction: column;
    align-items: stretch;

    a {
      text-align: left;
      justify-content: flex-start;
      width: 100%;
      padding-left: 24px;
      padding-top: 18px;
      padding-bottom: 18px;
    }
  }
}
```

