function countArrayItems(arr) {
    let mainCount = 0;
    let nestedCount = 0;

    arr.forEach(item => {
        if (Array.isArray(item)) {
            nestedCount += item.length;
        } else {
            mainCount++;
        }
    });

    return {
        totalMainItems: mainCount,
        totalNestedItems: nestedCount,
        totalItems: mainCount + nestedCount
    };
