#include <iostream>
#include <string>
#include <stack>
#include <stdexcept>
#include <cctype>
#include <climits>
#include <set>

using namespace std;

// Check valid characters
const set<char> validOps = {'+', '-', '*', '/', '(', ')'};

// Overflow check for addition
bool will_add_overflow(long long a, long long b) {
    if ((b > 0) && (a > LLONG_MAX - b)) return true;
    if ((b < 0) && (a < LLONG_MIN - b)) return true;
    return false;
}

// Overflow check for multiplication
bool will_mul_overflow(long long a, long long b) {
    if (a == 0 || b == 0) return false;
    if (a > 0 && b > 0 && a > LLONG_MAX / b) return true;
    if (a > 0 && b < 0 && b < LLONG_MIN / a) return true;
    if (a < 0 && b > 0 && a < LLONG_MIN / b) return true;
    if (a < 0 && b < 0 && a < LLONG_MAX / b) return true;
    return false;
}

int precedence(char op) {
    if(op == '+'||op == '-') return 1;
    if(op == '*'||op == '/') return 2;
    return 0;
}

// Applies the operator; checks errors
long long applyOp(long long a, long long b, char op) {
    switch(op){
        case '+':
            if (will_add_overflow(a, b)) 
                throw runtime_error("Integer overflow in addition");
            return a + b;
        case '-':
            if (will_add_overflow(a, -b)) 
                throw runtime_error("Integer overflow in subtraction");
            return a - b;
        case '*':
            if (will_mul_overflow(a, b))
                throw runtime_error("Integer overflow in multiplication");
            return a * b;
        case '/':
            if (b == 0)
                throw runtime_error("Division by zero");
            // Allowing integer division
            return a / b;
        default:
            throw runtime_error(string("Invalid operator: ") + op);
    }
}
```

---

### Main Expression Evaluator

```cpp
long long evaluate(const string& tokens) {
    stack<long long> values;
    stack<char> ops;
    int i = 0;
    int len = tokens.length();

    while (i < len) {
        if (isspace(tokens[i])) {
            i++;
            continue;
        }

        // Check invalid characters
        if (!isdigit(tokens[i]) && (validOps.find(tokens[i]) == validOps.end())) {
            throw runtime_error(string("Invalid character: ") + tokens[i]);
        }

        if (tokens[i] == '(') {
            ops.push(tokens[i]);
            i++;
        }
        else if (isdigit(tokens[i])) {
            long long val = 0;
            bool overflow = false;
            while (i < len && isdigit(tokens[i])) {
                int digit = tokens[i] - '0';
                // Check for overflow before multiplying/adding
                if (val > (LLONG_MAX - digit) / 10) 
                    overflow = true;
                val = val * 10 + digit;
                i++;
            }
            if(overflow)
                throw runtime_error("Integer overflow in value parsing");
            values.push(val);
        }
        else if (tokens[i] == ')') {
            while (!ops.empty() && ops.top() != '(') {
                if (values.size() < 2) 
                    throw runtime_error("Malformed expression: not enough operands");
                long long val2 = values.top(); values.pop();
                long long val1 = values.top(); values.pop();
                char op = ops.top(); ops.pop();
                long long result = applyOp(val1, val2, op);
                values.push(result);
            }
            if (ops.empty())
                throw runtime_error("Malformed expression: unmatched ')'");
            ops.pop(); // pop '('
            i++;
        }
        else { // operator (+, -, *, /)
            while (!ops.empty() && precedence(ops.top()) >= precedence(tokens[i])) {
                if (values.size() < 2)
                    throw runtime_error("Malformed expression: not enough operands");
                long long val2 = values.top(); values.pop();
                long long val1 = values.top(); values.pop();
                char op = ops.top(); ops.pop();
                long long result = applyOp(val1, val2, op);
                values.push(result);
            }
            ops.push(tokens[i]);
            i++;
        }
    }

    while (!ops.empty()) {
        if (values.size() < 2)
            throw runtime_error("Malformed expression: not enough operands at end");
        char op = ops.top(); ops.pop();
        long long val2 = values.top(); values.pop();
        long long val1 = values.top(); values.pop();
        long long result = applyOp(val1, val2, op);
        values.push(result);
    }
    if (values.size() != 1)
        throw runtime_error("Malformed expression: leftover values");
    return values.top();
}
```

