    string expressions[] = {
        "10 + 2 * 6",
        "100 * 2 + 12",
        "100 * ( 2 + 12 )",
        "100 * ( 2 + 12 ) / 14",
        "100 / 0",                    // Division by zero
        "2 + (3 * 4",                 // Unbalanced (
        "2 + 3 * ) 4 (",              // Mismatched parens
        "abc + 4",                    // Invalid char
        "9223372036854775807 + 1",    // Overflow
        "1 + 2 + ",                   // Missing operand
        "++1",                        // Malformed expr
    };
    for(const string& expr : expressions) {
