    // Initial table data
    let tableData = [
      { name: 'John',  age: 20 },
      { name: 'Alice', age: 22 }
    ];
    let sortState = { key: null, direction: 1 }; // 1 = asc, -1 = desc

    const tableBody = document.querySelector('#data-table tbody');
    const headers = document.querySelectorAll('#data-table th[data-key]');
    const errorSpan = document.getElementById('error-message');

    // Helper: render table
    function renderTable() {
      tableBody.innerHTML = '';
      tableData.forEach((row, idx) => {
        let tr = document.createElement('tr');
        // Row index
        let tdIndex = document.createElement('td');
        tdIndex.textContent = idx + 1;
        tr.appendChild(tdIndex);

        // Each column in order
        let tdName = document.createElement('td');
        tdName.textContent = row.name;
        tr.appendChild(tdName);

        let tdAge = document.createElement('td');
        tdAge.textContent = row.age;
        tr.appendChild(tdAge);

        tableBody.appendChild(tr);
      });
    }

    // Helper: clear header classes
    function clearSortIndicators() {
      headers.forEach(th => {
        th.classList.remove('sorted-asc', 'sorted-desc');
      });
    }

    // Sorting handler
    headers.forEach(th => {
      const key = th.dataset.key;
      if(key === 'index') return; // Skip
      th.addEventListener('click', function() {
        let direction = 1;
        if (sortState.key === key) {
          direction = -sortState.direction; // Toggle direction
        }
        sortState = { key, direction };

        tableData.sort((a, b) => {
          let valA = a[key], valB = b[key];
          if (key === 'age') { // Numeric equality
            valA = Number(valA);
            valB = Number(valB);
          } else {
            valA = String(valA).toLowerCase();
            valB = String(valB).toLowerCase();
          }
          if (valA < valB) return -1 * direction;
          if (valA > valB) return  1 * direction;
          return 0;
        });
        clearSortIndicators();
        th.classList.add(direction === 1 ? 'sorted-asc' : 'sorted-desc');
        renderTable();
      });
    });

    // Validation
    function validateRow(name, age) {
      if (!name.trim()) {
        return "Name cannot be empty";
      }
      if (!/^[A-Za-z\s\-']+$/.test(name)) {
        return "Name must be letters, spaces, -, or '";
      }
      if (!String(age).trim() || isNaN(age)) {
        return "Age must be a number";
      }
      if (parseInt(age) < 0) {
        return "Age must be 0 or greater";
      }
      if (!Number.isInteger(Number(age))) {
        return "Age must be an integer";
      }
      return "";
    }

    // Add-row form handler
    document.getElementById('add-form').addEventListener('submit', function(e) {
      e.preventDefault();
      const form = e.target;
      const name = form.name.value.trim();
      const age = form.age.value.trim();

      const err = validateRow(name, age);
      if (err) {
        errorSpan.textContent = err;
        return;
      }
      errorSpan.textContent = '';
      tableData.push({name, age: parseInt(age)});
      renderTable();

      // If sort was active, keep table sorted
      if (sortState.key) {
        document.querySelector(`th[data-key=${sortState.key}]`)?.click();
      }
      form.reset();
    });

    // Initial table render
    renderTable();
  </script>
</body>
</html>
