Certainly! Here is a JavaScript class named `PetCounter` that does exactly what you described. It supports storing counts for various pet types (by default supports at least `cats` and `dogs`), allows updating counts, checks for invalid types, and can generate a summary report.

```javascript
class PetCounter {
    constructor(location, allowedTypes = ['cats', 'dogs']) {
        this.location = location;
        // Set of allowed pet types, stored in lower case for consistency
        this.allowedTypes = new Set(allowedTypes.map(type => type.toLowerCase()));
        // Initialize the counts as an object with allowed types keys, all zero
        this.petCounts = {};
        this.allowedTypes.forEach(type => this.petCounts[type] = 0);
    }

    // Add or set count for a given pet type
    updatePetCount(petType, count) {
        if (typeof petType !== 'string' || !this.allowedTypes.has(petType.toLowerCase())) {
            throw new Error(`Invalid pet type: ${petType}. Allowed types are: ${Array.from(this.allowedTypes).join(", ")}`);
        }
        if (!Number.isInteger(count) || count < 0) {
            throw new Error("Count must be a non-negative integer.");
        }
        this.petCounts[petType.toLowerCase()] = count;
    }

    // Increment (or decrement) pet count
    changePetCount(petType, delta) {
        if (typeof petType !== 'string' || !this.allowedTypes.has(petType.toLowerCase())) {
            throw new Error(`Invalid pet type: ${petType}. Allowed types are: ${Array.from(this.allowedTypes).join(", ")}`);
        }
        if (!Number.isInteger(delta)) {
            throw new Error("delta must be an integer.");
        }
        const curr = this.petCounts[petType.toLowerCase()];
        const newCount = curr + delta;
        if (newCount < 0) {
            throw new Error(`Count for ${petType} cannot be negative.`);
        }
        this.petCounts[petType.toLowerCase()] = newCount;
    }

    // Get total number of pets
    getTotalPets() {
        return Object.values(this.petCounts).reduce((a, b) => a + b, 0);
    }

    // Get summary breakdown
    getSummary() {
        return {
            location: this.location,
            totalPets: this.getTotalPets(),
            breakdown: { ...this.petCounts }
        };
    }

    // Optionally, allow adding new valid pet types
    addPetType(newType) {
        const t = newType.toLowerCase();
        if (this.allowedTypes.has(t)) {
            throw new Error(`${newType} is already a valid pet type.`);
        }
        this.allowedTypes.add(t);
        this.petCounts[t] = 0;
    }
}


