## 3. JavaScript (`game.js`)

```javascript
const gameArea = document.getElementById('gameArea');
const basket = document.getElementById('basket');
const scoreDisplay = document.getElementById('score');
const gameOverDiv = document.getElementById('gameOver');

const areaWidth = 400;
const areaHeight = 600;
let basketX = 180;
const basketWidth = 60;
let score = 0;
let gameInterval;
let fallingObjects = [];
let gameRunning = true;

document.addEventListener('keydown', moveBasket);

function moveBasket(e) {
  if (!gameRunning) return;
  if (e.key === "ArrowLeft") {
    basketX -= 20;
    if (basketX < 0) basketX = 0;
    basket.style.left = basketX + 'px';
  }
  if (e.key === "ArrowRight") {
    basketX += 20;
    if (basketX > areaWidth - basketWidth) basketX = areaWidth - basketWidth;
    basket.style.left = basketX + 'px';
  }
}

function createFallingObject() {
  const obj = document.createElement('div');
  obj.classList.add('falling');
  obj.style.left = Math.floor(Math.random() * (areaWidth - 30)) + 'px';
  obj.style.top = '0px';
  gameArea.appendChild(obj);
  fallingObjects.push(obj);
}

function updateFallingObjects() {
  for (let i = fallingObjects.length - 1; i >= 0; i--) {
    const obj = fallingObjects[i];
    let top = parseInt(obj.style.top);
    top += 5 + Math.floor(score/5); // Faster as score increases
    obj.style.top = top + 'px';

    // Check for catch
    let objLeft = parseInt(obj.style.left);
    if (
      top + 30 >= areaHeight - 40 &&
      objLeft + 30 > basketX &&
      objLeft < basketX + basketWidth
    ) {
      // Caught!
      score++;
      scoreDisplay.textContent = "Score: " + score;
      gameArea.removeChild(obj);
      fallingObjects.splice(i, 1);
      continue;
    }

    // Missed (bottom)
    if (top > areaHeight - 30) {
      endGame();
      return;
    }
  }
}

function gameLoop() {
  if (!gameRunning) return;
  if (Math.random() < 0.04) createFallingObject();
  updateFallingObjects();
}

function endGame() {
  gameRunning = false;
  clearInterval(gameInterval);
  gameOverDiv.style.display = 'block';
}

function restartGame() {
  // Reset
  score = 0;
  scoreDisplay.textContent = "Score: 0";
  basketX = 180;
  basket.style.left = basketX + 'px';
  fallingObjects.forEach(obj => {
    if (obj.parentNode) obj.parentNode.removeChild(obj);
  });
  fallingObjects = [];
  gameOverDiv.style.display = 'none';
  gameRunning = true;
  gameInterval = setInterval(gameLoop, 20);
}

function startGame() {
  gameRunning = true;
  gameInterval = setInterval(gameLoop, 20);
}

startGame();
```

