Here’s a **simple, self-contained HTML example** that:

- Dynamically creates two checkboxes, a button (initially disabled), and a text field with JavaScript
- Enables the button **only** when **both checkboxes are checked**
- Shows the current value of the text field in a pop-up alert when the button is clicked

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Checkbox Enable Button Example</title>
</head>
<body>
  <div id="app"></div>

  <script>
    // Get the container div
    const appDiv = document.getElementById('app');

    // Create elements
    const checkbox1 = document.createElement('input');
    checkbox1.type = 'checkbox';
    checkbox1.id = 'cb1';

    const label1 = document.createElement('label');
    label1.htmlFor = 'cb1';
    label1.textContent = 'Checkbox 1';

    const checkbox2 = document.createElement('input');
    checkbox2.type = 'checkbox';
    checkbox2.id = 'cb2';

    const label2 = document.createElement('label');
    label2.htmlFor = 'cb2';
    label2.textContent = 'Checkbox 2';

    const input = document.createElement('input');
    input.type = 'text';
    input.placeholder = "Type something...";

    const button = document.createElement('button');
    button.textContent = 'Show Text';
    button.disabled = true;

    // Function to check if both checkboxes are checked
    function checkCheckboxes() {
      button.disabled = !(checkbox1.checked && checkbox2.checked);
    }

    checkbox1.addEventListener('change', checkCheckboxes);
    checkbox2.addEventListener('change', checkCheckboxes);

    button.addEventListener('click', function() {
      alert(input.value);
    });

    // Add all to the DOM
    appDiv.appendChild(checkbox1);
    appDiv.appendChild(label1);
    appDiv.appendChild(document.createElement('br'));

    appDiv.appendChild(checkbox2);
    appDiv.appendChild(label2);
    appDiv.appendChild(document.createElement('br'));

    appDiv.appendChild(input);
    appDiv.appendChild(document.createElement('br'));

    appDiv.appendChild(button);
  </script>
</body>
</html>
```

**How it works:**
- Both checkboxes must be checked to enable the button.
- Enter text in the input field.
- When you click the button, your text appears in a pop-up alert.

