### **GPA Calculation in JavaScript (MongoDB Shell/Node.js style)**

```js
// Calculate GPA for a learner in a given semester:
function computeGPA(learner_id, semester) {
  const performance = db.Learner_Performances.findOne({learner_id: learner_id, semester: semester});
  if (!performance) {
    print(`No record found for ${learner_id} in ${semester}`);
    return null;
  }
  let totalPoints = 0, totalCredits = 0;
  for (let cg of performance.grades) {
    let gpa = gradeToGPA[cg.grade];
    let credits = courseWeights[cg.course] || 3; // default to 3 credits if unknown
    if (gpa !== undefined) {
      totalPoints += gpa * credits;
      totalCredits += credits;
    }
  }
  if (totalCredits === 0) return 0;
  return (totalPoints/totalCredits).toFixed(2);
}

// Example: calculate Alice's (L001) GPA for 2022-Fall
print("L001 GPA 2022-Fall:", computeGPA("L001", "2022-Fall"));
```

